use crate::{PortfolioEngine,Result,digest,js_stringify,canonical_hash,publication::Publication};
use serde_json::{Value as V,json};use sha2::{Digest,Sha256};use std::{fs::File,io::{BufRead,BufReader,Read},path::Path};
const LIMIT:u64=16*1024*1024;
fn need(v:bool,c:&str)->Result<()>{if v{Ok(())}else{Err(format!("PORTFOLIO_IMPORT_{c}"))}}
fn hex(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))}
struct Prefix{reader:BufReader<std::io::Take<File>>,bytes:u64,hash:Sha256,end:u64}
impl Prefix{fn open(path:&Path,end:u64)->Result<Self>{let file=File::open(path).map_err(|_|"PORTFOLIO_IMPORT_OPEN")?;need(file.metadata().map_err(|_|"PORTFOLIO_IMPORT_METADATA")?.len()>=end,"PREFIX_TRUNCATED")?;Ok(Self{reader:BufReader::with_capacity(1024*1024,file.take(end)),bytes:0,hash:Sha256::new(),end})}fn row(&mut self)->Result<Option<V>>{let mut line=vec![];let n=self.reader.by_ref().take(LIMIT+2).read_until(b'\n',&mut line).map_err(|_|"PORTFOLIO_IMPORT_READ")?;if n==0{return Ok(None)}need(n as u64<=LIMIT+1&&line.last()==Some(&b'\n'),"PARTIAL_OR_OVERSIZE")?;self.bytes+=n as u64;self.hash.update(&line);let row:V=serde_json::from_slice(&line).map_err(|_|"PORTFOLIO_IMPORT_JSON")?;need(js_stringify(&row).as_bytes()==&line[..line.len()-1],"CANONICAL_BYTES")?;Ok(Some(row))}fn sha(&self)->String{format!("{:x}",self.hash.clone().finalize())}fn finish(&self,expected:&str)->Result<()>{need(self.bytes==self.end&&self.sha()==expected,"PREFIX_HASH")}}
#[derive(Clone,Debug,serde::Serialize)]#[serde(rename_all="camelCase")]
pub struct ImportEvidence{pub schema_version:u8,pub mode:&'static str,pub bank_hash:String,pub canonical_bank_hash:String,pub journal_bytes:u64,pub journal_hash:String,pub journal_records:u64,pub journal_tail_hash:String,pub wallet_state_hash:String,pub wallet_source_bytes:u64,pub wallet_source_sequence:i64,pub wallet_source_hash:String,pub public_source_bytes:u64,pub public_source_hash:String,pub public_source_sequence:i64,pub public_source_tail_hash:String,pub wallet_publication_state:V,pub public_snapshot_state:V,pub original_bank_unchanged:bool,pub official_holdings_adopted:bool,pub all_original_checkpoints_verified:bool,pub historical_not_current:bool,pub authoritative_overlay_applied:bool}
// Base V1 histories are historical when an authoritative operator overlay is
// active. Never reintroduce the obsolete held position from that base journal.
fn reject_unhandled_overlay(checkpoint:&Path,bank:&V)->Result<()>{if bank["mode"]=="funded_settlement_value_paper_v1"{if let Some(cohort)=checkpoint.parent(){need(!cohort.join("operator-value-revision/opening.json").exists()&&!cohort.join("operator-value-revision/journal.jsonl").exists(),"AUTHORITATIVE_OVERLAY_REQUIRES_EXPLICIT_IMPORT")?;}if let Some(runtime)=checkpoint.parent().and_then(Path::parent).and_then(Path::parent){need(!runtime.join("FUNDAMENTAL_VALUE_REVISION").exists(),"AUTHORITATIVE_OVERLAY_REQUIRES_EXPLICIT_IMPORT")?;}}Ok(())}
 fn import_impl(bank:V,checkpoint_path:&Path,prefix_bytes:u64,prefix_sha:&str,public_source_path:&Path,public_prefix_bytes:u64,public_prefix_sha:&str,historical:bool)->Result<(PortfolioEngine,ImportEvidence)>{need(hex(prefix_sha)&&hex(public_prefix_sha)&&prefix_bytes>0&&public_prefix_bytes>0,"BINDING")?;if !historical{reject_unhandled_overlay(checkpoint_path,&bank)?;}let mut engine=PortfolioEngine::new(bank.clone())?;let bank_hash=digest(&bank);let mut journal=Prefix::open(checkpoint_path,prefix_bytes)?;let mut source=Prefix::open(public_source_path,public_prefix_bytes)?;let mut publication=Publication::new(&bank["universe"])?;let original_sequence=bank["sourcePrefixSequence"].as_i64().ok_or("PORTFOLIO_IMPORT_BANK_PREFIX")?;let original_bytes=bank["sourcePrefixBytes"].as_u64().ok_or("PORTFOLIO_IMPORT_BANK_PREFIX")?;while publication.sequence()<original_sequence{let row=source.row()?.ok_or("PORTFOLIO_IMPORT_SOURCE_TRUNCATED")?;publication.apply(&row)?;}need(source.bytes==original_bytes&&source.sha()==bank["sourcePrefixHash"].as_str().unwrap_or("")&&publication.tail_hash()==bank["sourcePrefixJournalHash"].as_str().unwrap_or(""),"ORIGINAL_BANK_PREFIX")?;need(crate::time(&publication.value()["lastAt"])?<=crate::time(&bank["cutoff"] )?,"ORIGINAL_FUTURE_CUTOFF")?;let mut records=0u64;let mut previous=if bank["mode"]=="funded_settlement_value_paper_v1"{bank_hash.clone()}else{String::new()};let mut wallet_frontier=source.bytes;let mut wallet_publication=publication.value();
 while let Some(row)=journal.row()?{records+=1;let hash=row["hash"].as_str().ok_or("PORTFOLIO_IMPORT_JOURNAL_HASH")?.to_owned();let mut body=row.clone();body.as_object_mut().ok_or("PORTFOLIO_IMPORT_BODY")?.shift_remove("hash");need(row["sequence"].as_u64()==Some(records)&&row["previous"].as_str()==Some(previous.as_str())&&hex(&hash)&&digest(&body)==hash,"JOURNAL_CHAIN")?;previous=hash;
  if bank["mode"]=="funded_settlement_value_paper_v1"{need(row["bankHash"]==bank_hash,"LEGACY_BANK")?;let kind=row["kind"].as_str().ok_or("PORTFOLIO_IMPORT_KIND")?;if records==1{need(kind=="genesis"&&row["stateHash"]==digest(engine.state()),"LEGACY_GENESIS")?;}else{need(kind=="batch","LEGACY_EVENT")?;let target=row["sourceSequence"].as_i64().ok_or("PORTFOLIO_IMPORT_FRONTIER")?;need(target>publication.sequence(),"SOURCE_FORWARD")?;let at=row["availableAt"].as_str().ok_or("PORTFOLIO_IMPORT_CLOCK")?;let account=if row["accountEligibility"].is_null(){None}else{Some(&row["accountEligibility"])};while publication.sequence()<target{let original=source.row()?.ok_or("PORTFOLIO_IMPORT_SOURCE_TRUNCATED")?;publication.apply(&original)?;engine.apply(&original,at,account)?;}need(row["sourceBytes"].as_u64()==Some(source.bytes)&&row["sourceHash"].as_str()==Some(publication.tail_hash())&&row["stateHash"]==digest(engine.state()),"LEGACY_EXACT_STATE_CHECKPOINT")?;}}
  else{let event=&row["event"];if records==1{need(event["kind"]=="genesis"&&event["bankHash"]==bank_hash&&event["cutoff"]==bank["cutoff"],"GENESIS")?;}else{need(event["kind"]=="source_batch","EVENT")?;let rows=event["rows"].as_array().ok_or("PORTFOLIO_IMPORT_ROWS")?;need(!rows.is_empty(),"EMPTY_SOURCE_BATCH")?;let at=event["availableAt"].as_str().ok_or("PORTFOLIO_IMPORT_CLOCK")?;let account=if event["accountEligibility"].is_null(){None}else{Some(&event["accountEligibility"])};for recorded in rows{let original=source.row()?.ok_or("PORTFOLIO_IMPORT_SOURCE_TRUNCATED")?;need(js_stringify(&original)==js_stringify(recorded),"ACTUAL_SOURCE_ROW")?;publication.apply(&original)?;engine.apply(&original,at,account)?;}}
   let expected=json!({"paper":engine.state(),"sourceBytes":source.bytes,"sourceSequence":publication.sequence(),"sourceHash":publication.tail_hash(),"sourcePrefixHash":source.sha()});need(canonical_hash(&row["state"])==canonical_hash(&expected),"EXACT_FUNDED_STATE_CHECKPOINT")?;}
  wallet_frontier=source.bytes;wallet_publication=publication.value();
 }
 need(records>0,"EMPTY_HISTORY")?;journal.finish(prefix_sha)?;while let Some(row)=source.row()?{publication.apply(&row)?;}source.finish(public_prefix_sha)?;let evidence=ImportEvidence{schema_version:1,mode:"native_original_funded_history_import_v1",bank_hash:bank_hash.clone(),canonical_bank_hash:canonical_hash(&bank),journal_bytes:prefix_bytes,journal_hash:prefix_sha.into(),journal_records:records,journal_tail_hash:previous,wallet_state_hash:digest(engine.state()),wallet_source_bytes:wallet_frontier,wallet_source_sequence:wallet_publication["sequence"].as_i64().unwrap(),wallet_source_hash:wallet_publication["hash"].as_str().unwrap().into(),public_source_bytes:public_prefix_bytes,public_source_hash:public_prefix_sha.into(),public_source_sequence:publication.sequence(),public_source_tail_hash:publication.tail_hash().into(),wallet_publication_state:wallet_publication,public_snapshot_state:publication.value(),original_bank_unchanged:digest(engine.bank())==bank_hash,official_holdings_adopted:false,all_original_checkpoints_verified:true,historical_not_current:historical,authoritative_overlay_applied:false};Ok((engine,evidence))}

pub fn import_history(bank:V,checkpoint_path:&Path,prefix_bytes:u64,prefix_sha:&str,public_source_path:&Path,public_prefix_bytes:u64,public_prefix_sha:&str)->Result<(PortfolioEngine,ImportEvidence)>{import_impl(bank,checkpoint_path,prefix_bytes,prefix_sha,public_source_path,public_prefix_bytes,public_prefix_sha,false)}
pub fn import_historical_base_for_overlay(bank:V,checkpoint_path:&Path,prefix_bytes:u64,prefix_sha:&str,public_source_path:&Path,public_prefix_bytes:u64,public_prefix_sha:&str,opening:&V)->Result<(PortfolioEngine,ImportEvidence)>{need(bank["mode"]=="funded_settlement_value_paper_v1"&&opening["originalBankHash"]==digest(&bank)&&opening["originalJournalBytes"].as_u64()==Some(prefix_bytes)&&opening["originalJournalHash"].as_str()==Some(prefix_sha),"HISTORICAL_OPENING_ANCHOR")?;let bank_file=checkpoint_path.parent().ok_or("PORTFOLIO_IMPORT_BANK_PATH")?.join("bank.json");let bytes=std::fs::read(bank_file).map_err(|_|"PORTFOLIO_IMPORT_BANK_FILE")?;let original:V=serde_json::from_slice(&bytes).map_err(|_|"PORTFOLIO_IMPORT_BANK_FILE")?;need(format!("{:x}",Sha256::digest(&bytes))==opening["originalBankFileHash"].as_str().unwrap_or("")&&digest(&original)==digest(&bank)&&opening["originalStatsHash"]==digest(&opening["originalStats"]),"HISTORICAL_BANK_AND_STATS")?;let(engine,evidence)=import_impl(bank,checkpoint_path,prefix_bytes,prefix_sha,public_source_path,public_prefix_bytes,public_prefix_sha,true)?;let stats=&opening["originalStats"];need(stats["bankHash"]==evidence.bank_hash&&stats["stateHash"]==evidence.wallet_state_hash&&stats["sourceBytes"].as_u64()==Some(evidence.wallet_source_bytes)&&stats["sourceSequence"].as_i64()==Some(evidence.wallet_source_sequence)&&stats["sourceHash"]==evidence.wallet_source_hash,"HISTORICAL_EXACT_STATE_ANCHOR")?;let at=stats["updatedAt"].as_str().ok_or("PORTFOLIO_IMPORT_STATS_CLOCK")?;need(canonical_hash(&engine.report(at)?["wallets"])==canonical_hash(&stats["wallets"]),"HISTORICAL_EXACT_ACCOUNTING")?;Ok((engine,evidence))}
